effect.shader:

    vec4 newLayer( vec4 a, vec4 b) {
    return a * (1. - b.a) + b;
    }

    mat2 rot2m(float a){

	float s = sin(a);
	float c = cos(a);

	return mat2(c, -s, s, c);
    }

    vec2 l2s( vec2 v ) {
        return (vec4(v,0.,1.)*acLayerToScreen).xy;
    }

   #define fragCoord gl_FragCoord.xy

   /////////////////////////



   /////////////////////////
    void main ()
    {
        if( acPass == 0 ) {
            gl_FragColor = texture2DCv(inputImg.texture, acScreenNorm.st);
            }
        else if( acPass==1 ) {
        vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
        vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

        vec2 umefx;
        umefx = acScreenNorm; 
        /////////////////////////

            const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);
            //////////////////////////
            float luminance = dot(texColor.rgb, luminanceWeighting);
            float f = max(min((feathera/4.),abs(0.5-(1.-threshold))),0.00196);
            float t = (((1.-threshold)-0.5)*(1.003+f*2.))+0.5;
            float p = smoothstep(t-f, t+f, luminance);

            vec3 rgb = vec3(p,p,p);

            vec4 trisolt = vec4(rgb,texColor.a);
            //////////////////////////
            vec4 targetLuma = trisolt ;
            float luma = dot(targetLuma.rgb, luminanceWeighting);
            float lowThresholdB = (lowThreshold*(1.0+featherb))-0.0001;
            float lowThresholdA = lowThresholdB-max(featherb,0.00001);
            float highThresholdA = (highThreshold*(1.0+featherb)-featherb)+0.0001;
            float highThresholdB = highThresholdA+max(featherb,0.00001);
            float lowBlend = smoothstep( lowThresholdA, lowThresholdB, luma );
            float highBlend = 1. - smoothstep( highThresholdA, highThresholdB, luma );
            float lumafx = min(lowBlend,highBlend);
            vec4 antiblack = targetLuma * lumafx;

            float a = angle * 0.0174533;
            vec2 st = acLayerNorm;
            st -= 0.5;
            st -= (offset*vec2(1,-1)) / 500.;
            st /= scale;
            st *= mat2(sin(a), -cos(a), cos(a), sin(a));
            st += 0.5;
            float tx = length( st - 0.5 ) * 2.0;
            tx = clamp(tx,0.0,1.0);

            vec4 color = mix(color1, color2, tx);

            antiblack = vec4(antiblack.rgb*(gradColor? color.rgb : color1.rgb), antiblack.a);

    	gl_FragColor = mix(texColor, antiblack, alpha);
    	}

    	// }
    }
